const STAGES=['lead','registered','onboarding','active','maintenance','paused','lapsed'];
const S={api:'https://api.shiftsometimber.co.uk',people:[],tasks:[],current:null,orders:[],products:[],content:[],articles:[],tickets:[],hqUsers:[],audit:[],me:null,mfaChallenge:null};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
async function call(path,opts={}){const r=await fetch(S.api+path,{...opts,credentials:'include',headers:{'Accept':'application/json','Content-Type':'application/json',...(opts.headers||{})}});let j={};try{j=await r.json()}catch{}if(!r.ok){const e=new Error(j.message||j.error||`Shift Core ${r.status}`);e.status=r.status;e.data=j;throw e}return j}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const personName=p=>[p.first_name,p.last_name].filter(Boolean).join(' ')||'Unnamed Shifter';
function fmt(d,withTime=false){if(!d)return '—';try{return new Date(d).toLocaleString('en-GB',withTime?{dateStyle:'medium',timeStyle:'short'}:{day:'numeric',month:'short',year:'numeric'})}catch{return d}}
function badge(v){return `<span class="badge">${esc((v||'—').replaceAll('_',' '))}</span>`}
function setConnected(on,msg){$('#connectionDot').classList.toggle('on',on);$('#notice').textContent=msg;$('#notice').classList.toggle('ok',on)}
function rows(list){$('#peopleRows').innerHTML=list.length?list.map(p=>`<tr data-person="${p.id}"><td class="person"><b>${esc(personName(p))}</b><span>${esc(p.email)}</span></td><td>${badge(p.lifecycle_stage||'registered')}</td><td>${badge(p.membership_status||'none')}</td><td>${esc(p.source||'—')}</td><td>${Number(p.case_count||0)}</td><td>${esc(fmt(p.last_activity_at||p.created_at))}</td></tr>`).join(''):'<tr><td colspan="6">No matching people.</td></tr>';$$('[data-person]').forEach(r=>r.onclick=()=>openPerson(Number(r.dataset.person)))}
function renderPipeline(){const counts={};STAGES.forEach(s=>counts[s]=0);S.people.forEach(p=>counts[p.lifecycle_stage||'registered']=(counts[p.lifecycle_stage||'registered']||0)+1);const max=Math.max(1,...Object.values(counts));$('#pipelineMini').innerHTML=STAGES.slice(0,5).map(s=>`<div class="mini-row"><span>${esc(s)}</span><div class="bar"><i style="width:${(counts[s]||0)/max*100}%"></i></div><b>${counts[s]||0}</b></div>`).join('');$('#pipelineBoard').innerHTML=STAGES.map(s=>`<section class="stage-col"><h3>${esc(s)} <span>${counts[s]||0}</span></h3>${S.people.filter(p=>(p.lifecycle_stage||'registered')===s).map(p=>`<div class="stage-card" data-person="${p.id}"><b>${esc(personName(p))}</b><span>${esc(p.email)}</span><span>${esc(fmt(p.last_activity_at||p.created_at))}</span></div>`).join('')||'<div class="empty">No people</div>'}</section>`).join('');$$('#pipelineBoard [data-person]').forEach(x=>x.onclick=()=>openPerson(Number(x.dataset.person)))}
function renderTasks(){const filter=$('#taskFilter')?.value||'open';let arr=S.tasks;if(filter==='open')arr=arr.filter(t=>t.status!=='done');if(filter==='done')arr=arr.filter(t=>t.status==='done');$('#taskList').innerHTML=arr.length?arr.map(t=>`<div class="task-row ${t.status==='done'?'done':''}"><input type="checkbox" data-task-toggle="${t.id}" ${t.status==='done'?'checked':''}><div><b>${esc(t.title)}</b><span>${esc(t.person_name||t.email||'General')} · ${t.due_at?'Due '+esc(fmt(t.due_at)):'No due date'}${t.assigned_to?' · '+esc(t.assigned_to):''}</span></div><small>${esc(t.status)}</small></div>`).join(''):'<div class="empty">No tasks in this view.</div>';$$('[data-task-toggle]').forEach(c=>c.onchange=async()=>{try{await call(`/v1/crm/tasks/${c.dataset.taskToggle}`,{method:'PATCH',body:JSON.stringify({status:c.checked?'done':'open'})});await loadTasks()}catch(e){alert(e.message)}});$('#taskMini').innerHTML=S.tasks.filter(t=>t.status!=='done').slice(0,4).map(t=>`<div class="feed-item"><b>${esc(t.title)}</b><span>${esc(t.person_name||t.email||'General')} · ${t.due_at?'Due '+esc(fmt(t.due_at)):'No due date'}</span></div>`).join('')||'<div class="empty">Nothing outstanding.</div>'}
async function loadTasks(){try{const j=await call('/v1/crm/tasks');S.tasks=j.tasks||[];renderTasks()}catch(e){S.tasks=[];renderTasks()}}
async function load(){
  try{
    const me=await call('/v1/hq/me');S.me=me.user;$('#hqUserChip').textContent=`${S.me.name} · ${S.me.role}`;$('#logoutBtn').hidden=false;
    const [st,pp]=await Promise.all([call('/v1/crm/stats'),call('/v1/crm/people')]);
    $('#total').textContent=st.stats.total;$('#registered').textContent=st.stats.registered;$('#cases').textContent=st.stats.cases;$('#orders').textContent=st.stats.pharmacyOrders;S.people=pp.people||[];rows(S.people);renderPipeline();
    $('#recent').innerHTML=S.people.slice(0,5).map(p=>`<div class="person" data-person="${p.id}" style="padding:10px 0;border-bottom:1px solid #e3e7e1;cursor:pointer"><b>${esc(personName(p))}</b><span>${esc(p.email)} · ${esc(p.lifecycle_stage||'registered')}</span></div>`).join('')||'<div class="empty">No people yet.</div>';
    $$('#recent [data-person]').forEach(x=>x.onclick=()=>openPerson(Number(x.dataset.person)));setConnected(true,'Shift HQ is securely signed in to live Shift Core.');await Promise.all([loadTasks(),loadDashboardIntelligence()]);
  }catch(e){S.me=null;$('#hqUserChip').textContent='Not signed in';$('#logoutBtn').hidden=true;setConnected(false,'Sign in to Shift HQ.');if(e.status===401&&!$('#connect').open)$('#connect').showModal();}
}
async function loadDashboardIntelligence(){try{const j=await call('/v1/hq/intelligence'),by=Object.fromEntries(j.signals.map(x=>[x.key,x]));$('#supportOpen').textContent=by.open_support?.count??0;$('#overdueTasks').textContent=by.overdue_tasks?.count??0;$('#newThisWeek').textContent=by.new_users?.count??0;$('#alertCount').textContent=j.signals.filter(x=>x.count&&x.severity!=='good').length;$('#brief').textContent=j.brief}catch{}}
function view(id){$$('.view').forEach(x=>x.classList.toggle('active',x.id===id));$$('nav button[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===id));const titles={people:'Your Shift CRM — one view of every person.',pipeline:'See where every Shifter is in their journey.',tasks:'Keep follow-ups and actions moving.',orders:'Every order from payment to fulfilment.',products:'Manage memberships, SKUs and services.',website:'Edit the parts of the website that should be editable.',knowledge:'Run the Knowledge Hub publishing workflow.',dashboard:'Good to see you. Here’s what’s happening at Shift.'};$('#title').textContent=titles[id]||titles.dashboard}
async function openPerson(id){S.current=id;$('#personModal').showModal();$('#personLoading').hidden=false;$('#personContent').hidden=true;try{const j=await call(`/v1/crm/people/${id}`);const p=j.person;$('#personTitle').textContent=personName(p);$('#personEmail').textContent=p.email||'';$('#personStage').innerHTML=STAGES.map(s=>`<option value="${s}" ${s===(p.lifecycle_stage||'registered')?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('');$('#personMembership').textContent=p.membership_status||'none';$('#personSource').textContent=p.source||'—';$('#personJoined').textContent=fmt(p.created_at);$('#contactDetails').innerHTML=[['Email',p.email],['Phone',p.phone],['Postcode',p.postcode],['Date of birth',p.date_of_birth],['Last login',fmt(p.last_login_at,true)]].map(([k,v])=>`<div class="kv"><span>${k}</span><b>${esc(v||'—')}</b></div>`).join('');$('#memberStats').innerHTML=[['Cases',j.cases?.length],['MOTs',j.assessments?.length],['Check-ins',j.checkIns?.length],['Pharmacy orders',j.pharmacyOrders?.length],['Consents',j.consents?.length]].map(([k,v])=>`<div class="kv"><span>${k}</span><b>${Number(v||0)}</b></div>`).join('');renderPersonNotes(j.notes||[]);renderPersonTasks(j.tasks||[]);renderTimeline(j);$('#personLoading').hidden=true;$('#personContent').hidden=false}catch(e){$('#personLoading').textContent='Could not load Member 360: '+e.message}}
function renderPersonNotes(notes){$('#notesList').innerHTML=notes.length?notes.map(n=>`<div class="feed-item"><b>${esc(n.note)}</b><span>${esc(n.created_by||'HQ')} · ${esc(fmt(n.created_at,true))}</span></div>`).join(''):'<div class="empty">No CRM notes yet.</div>'}
function renderPersonTasks(tasks){$('#personTasks').innerHTML=tasks.length?tasks.map(t=>`<div class="feed-item"><b>${esc(t.title)}</b><span>${esc(t.status)}${t.due_at?' · due '+esc(fmt(t.due_at)):''}</span></div>`).join(''):'<div class="empty">No tasks for this person.</div>'}
function renderTimeline(j){const events=[];(j.assessments||[]).forEach(x=>events.push({d:x.created_at,t:'Shift MOT',s:x.status||'completed'}));(j.checkIns||[]).forEach(x=>events.push({d:x.submitted_at,t:'Check-in',s:x.weight?`Weight ${x.weight}`:'Member check-in'}));(j.cases||[]).forEach(x=>events.push({d:x.created_at,t:'Case '+(x.reference||'#'+x.id),s:x.status}));(j.pharmacyOrders||[]).forEach(x=>events.push({d:x.created_at,t:'Pharmacy order',s:x.pharmacy_status||x.status}));events.sort((a,b)=>new Date(b.d)-new Date(a.d));$('#timeline').innerHTML=events.length?events.slice(0,30).map(e=>`<div class="timeline-event"><b>${esc(e.t)}</b><span>${esc(e.s||'')} · ${esc(fmt(e.d,true))}</span></div>`).join(''):'<div class="empty">No programme activity yet.</div>'}
$('#settings').onclick=async()=>{try{const me=await call('/v1/hq/me');S.me=me.user;$('#hqSettingsSummary').innerHTML=`<div class="kv"><span>User</span><b>${esc(S.me.name)} (${esc(S.me.email)})</b></div><div class="kv"><span>Role</span><b>${esc(S.me.role)}</b></div><div class="kv"><span>MFA</span><b>${S.me.mfaEnabled?'Enabled':'Not enabled'}</b></div>`;$('#mfaSetupBox').hidden=true;$('#hqSettingsDialog').showModal()}catch{$('#connect').showModal()}};
$('#logoutBtn').onclick=async()=>{try{await call('/v1/hq/auth/logout',{method:'POST',body:'{}'})}catch{}location.reload()};
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginMessage').textContent='Signing in…';try{const j=await call('/v1/hq/auth/login',{method:'POST',body:JSON.stringify({email:$('#hqEmail').value,password:$('#hqPassword').value})});if(j.mfaRequired){S.mfaChallenge=j.challenge;$('#connect').close();$('#mfaDialog').showModal();return}$('#connect').close();$('#loginMessage').textContent='';await load()}catch(err){$('#loginMessage').textContent=err.message}};
$('#mfaForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/auth/mfa/verify',{method:'POST',body:JSON.stringify({challenge:S.mfaChallenge,code:$('#mfaCode').value})});S.mfaChallenge=null;$('#mfaDialog').close();await load()}catch(err){alert(err.message)}};
$('#bootstrapOpen').onclick=()=>{$('#connect').close();$('#bootstrapDialog').showModal()};
$('#bootstrapForm').onsubmit=async e=>{e.preventDefault();$('#bootstrapMessage').textContent='Creating owner…';try{const r=await fetch(S.api+'/v1/hq/auth/bootstrap',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','X-Shift-Admin-Key':$('#bootstrapKey').value},body:JSON.stringify({name:$('#bootstrapName').value,email:$('#bootstrapEmail').value,password:$('#bootstrapPassword').value})});const j=await r.json();if(!r.ok)throw new Error(j.message||j.error);$('#bootstrapDialog').close();$('#hqEmail').value=$('#bootstrapEmail').value;$('#connect').showModal()}catch(err){$('#bootstrapMessage').textContent=err.message}};
$('#setupMfaBtn').onclick=async()=>{try{const j=await call('/v1/hq/mfa/setup',{method:'POST',body:'{}'});$('#mfaSetupBox').hidden=false;$('#mfaSetupBox').innerHTML=`<b>Authenticator secret</b><code>${esc(j.secret)}</code><p>Add this secret manually to your authenticator app, then enter its current 6-digit code.</p><input id="enableMfaCode" inputmode="numeric" maxlength="6" placeholder="123456"><button type="button" id="enableMfaNow" class="primary full-btn">Enable MFA</button><details><summary>Authenticator URI</summary><code>${esc(j.otpauthUri)}</code></details>`;$('#enableMfaNow').onclick=async()=>{try{await call('/v1/hq/mfa/enable',{method:'POST',body:JSON.stringify({code:$('#enableMfaCode').value})});alert('MFA enabled.');$('#hqSettingsDialog').close();await load()}catch(e){alert(e.message)}}}catch(e){alert(e.message)}};
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-open]').forEach(b=>b.onclick=()=>view(b.dataset.open));$('#search').oninput=e=>{const q=e.target.value.toLowerCase();rows(S.people.filter(p=>JSON.stringify(p).toLowerCase().includes(q)))};$('#taskFilter').onchange=renderTasks;$('#refreshPipeline').onclick=renderPipeline;$('#closePerson').onclick=()=>$('#personModal').close();
$('#personStage').onchange=async e=>{try{await call(`/v1/crm/people/${S.current}/stage`,{method:'PATCH',body:JSON.stringify({lifecycleStage:e.target.value})});await load();$('#personModal').close();await openPerson(S.current)}catch(err){alert(err.message)}};
$('#noteForm').onsubmit=async e=>{e.preventDefault();const note=$('#noteText').value.trim();if(!note)return;try{await call('/v1/crm/notes',{method:'POST',body:JSON.stringify({userId:S.current,note})});$('#noteText').value='';$('#personModal').close();await openPerson(S.current)}catch(err){alert(err.message)}};
$('#taskForm').onsubmit=async e=>{e.preventDefault();const title=$('#taskTitle').value.trim();if(!title)return;try{await call('/v1/crm/tasks',{method:'POST',body:JSON.stringify({userId:S.current,title,dueAt:$('#taskDue').value||null})});$('#taskTitle').value='';$('#taskDue').value='';await loadTasks();$('#personModal').close();await openPerson(S.current)}catch(err){alert(err.message)}};
async function loadSupport(){try{const j=await call('/v1/hq/support');S.tickets=j.tickets||[];renderSupport()}catch(e){$('#supportRows').innerHTML=`<tr><td colspan="6">${esc(e.message)}</td></tr>`}}
function renderSupport(){const f=$('#supportFilter')?.value||'open',a=f==='all'?S.tickets:S.tickets.filter(t=>f==='open'?t.status!=='closed':t.status===f);$('#supportRows').innerHTML=a.length?a.map(t=>`<tr><td><b>${esc(t.reference)}</b><br><small>${esc(t.subject)}</small></td><td>${esc(t.member_name||'—')}<br><small>${esc(t.member_email||'—')}</small></td><td class="support-priority-${esc(t.priority)}">${esc(t.priority)}</td><td>${badge(t.status)}</td><td>${esc(t.owner_name||'Unassigned')}</td><td>${esc(fmt(t.updated_at,true))}</td></tr>`).join(''):'<tr><td colspan="6">No tickets in this view.</td></tr>';$('#ticketOpen').textContent=S.tickets.filter(t=>t.status!=='closed').length;$('#ticketUrgent').textContent=S.tickets.filter(t=>t.status!=='closed'&&t.priority==='urgent').length;$('#ticketWaiting').textContent=S.tickets.filter(t=>t.status==='waiting').length;$('#ticketClosed').textContent=S.tickets.filter(t=>t.status==='closed').length}
async function loadIntelligence(){try{const j=await call('/v1/hq/intelligence');$('#intelligenceHero').innerHTML=`<div><p class="eyebrow">DAILY BRIEF · ${esc(fmt(j.generatedAt,true))}</p><h2>${esc(j.brief)}</h2></div>`;$('#intelligenceGrid').innerHTML=j.signals.map(s=>`<article class="intel-card ${esc(s.severity)}"><b>${esc(s.title)}</b><strong>${Number(s.count||0)}</strong><span>${esc(s.message)}</span></article>`).join('');await loadDashboardIntelligence()}catch(e){$('#intelligenceGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadHqUsers(){try{const j=await call('/v1/hq/users');S.hqUsers=j.users||[];$('#hqUserRows').innerHTML=S.hqUsers.map(u=>`<tr><td><b>${esc(u.name)}</b><br><small>${esc(u.email)}</small></td><td><span class="role-badge">${esc(u.role)}</span></td><td>${u.mfa_enabled?'Enabled':'Not enabled'}</td><td>${badge(u.status)}</td><td>${esc(fmt(u.last_login_at,true))}</td><td>${esc(fmt(u.created_at))}</td></tr>`).join('')||'<tr><td colspan="6">No HQ users.</td></tr>'}catch(e){$('#hqUserRows').innerHTML=`<tr><td colspan="6">${esc(e.message)}</td></tr>`}}
async function loadAudit(){try{const j=await call('/v1/hq/audit');S.audit=j.audit||[];$('#auditRows').innerHTML=S.audit.map(a=>`<tr><td>${esc(fmt(a.created_at,true))}</td><td>${esc(a.actor_name||a.actor_email||'Bootstrap')}</td><td>${esc(a.action)}</td><td>${esc(a.entity_type||'—')}</td><td>${esc(a.entity_id||'—')}</td></tr>`).join('')||'<tr><td colspan="5">No audit events yet.</td></tr>'}catch(e){$('#auditRows').innerHTML=`<tr><td colspan="5">${esc(e.message)}</td></tr>`}}
const section3View=view;view=function(id){section3View(id);if(id==='support')loadSupport();if(id==='intelligence')loadIntelligence();if(id==='users')loadHqUsers();if(id==='audit')loadAudit()}
$('#supportFilter').onchange=renderSupport;$('#newTicket').onclick=()=>{$('#ticketForm').reset();$('#ticketModal').showModal()};$('#ticketForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/support',{method:'POST',body:JSON.stringify({email:$('#ticketEmail').value,subject:$('#ticketSubject').value,priority:$('#ticketPriority').value,status:$('#ticketStatus').value,body:$('#ticketBody').value})});$('#ticketModal').close();await loadSupport()}catch(err){alert(err.message)}};
$('#refreshIntelligence').onclick=loadIntelligence;$('#refreshAudit').onclick=loadAudit;$('#newHqUser').onclick=()=>{$('#hqUserForm').reset();$('#hqUserModal').showModal()};$('#hqUserForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/users',{method:'POST',body:JSON.stringify({name:$('#newHqName').value,email:$('#newHqEmail').value,password:$('#newHqPassword').value,role:$('#newHqRole').value})});$('#hqUserModal').close();await loadHqUsers()}catch(err){alert(err.message)}};
$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close)?.close());

async function loadSegments(){try{const j=await call('/v1/hq/segments');S.segments=j.segments||[];$('#segmentRows').innerHTML=S.segments.map(s=>{let r={};try{r=JSON.parse(s.rule_json||'{}')}catch{}return `<tr><td><b>${esc(s.name)}</b></td><td>${esc(r.field||'—')} ${esc(r.operator||'')} ${esc(r.value||'')}</td><td>${Number(s.member_count||0)}</td><td>${badge(s.status)}</td><td>${esc(fmt(s.updated_at,true))}</td></tr>`}).join('')||'<tr><td colspan="5">No segments yet.</td></tr>';const sel=$('#campaignSegment');if(sel)sel.innerHTML='<option value="">All consented contacts</option>'+S.segments.map(s=>`<option value="${s.id}">${esc(s.name)} (${Number(s.member_count||0)})</option>`).join('')}catch(e){$('#segmentRows').innerHTML=`<tr><td colspan="5">${esc(e.message)}</td></tr>`}}
async function loadCampaigns(){try{const j=await call('/v1/hq/campaigns');S.campaigns=j.campaigns||[];$('#campaignRows').innerHTML=S.campaigns.map(c=>`<tr><td><b>${esc(c.name)}</b><br><small>${esc(c.subject||'')}</small></td><td><span class="channel-${esc(c.channel)}">${esc(c.channel)}</span></td><td>${esc(c.segment_name||'All consented')}</td><td>${badge(c.status)}</td><td>${esc(fmt(c.scheduled_at,true))}</td><td>${esc(fmt(c.created_at))}</td></tr>`).join('')||'<tr><td colspan="6">No campaigns yet.</td></tr>';$('#campaignDraft').textContent=S.campaigns.filter(x=>x.status==='draft').length;$('#campaignScheduled').textContent=S.campaigns.filter(x=>x.status==='scheduled').length;$('#campaignSent').textContent=S.campaigns.filter(x=>x.status==='sent').length;$('#campaignRecipients').textContent=S.campaigns.reduce((a,x)=>a+Number(x.recipient_count||0),0)}catch(e){$('#campaignRows').innerHTML=`<tr><td colspan="6">${esc(e.message)}</td></tr>`}}
async function loadForms(){try{const j=await call('/v1/hq/forms');S.leadForms=j.forms||[];$('#formRows').innerHTML=S.leadForms.map(f=>`<tr><td><b>${esc(f.name)}</b></td><td>/${esc(f.slug)}</td><td>${badge(f.status)}</td><td>${Number(f.submission_count||0)}</td><td>${esc(fmt(f.created_at))}</td></tr>`).join('')||'<tr><td colspan="5">No forms yet.</td></tr>'}catch(e){$('#formRows').innerHTML=`<tr><td colspan="5">${esc(e.message)}</td></tr>`}}
async function loadWorkflows(){try{const j=await call('/v1/hq/workflows');S.workflows=j.workflows||[];$('#workflowRows').innerHTML=S.workflows.map(w=>`<tr><td><b>${esc(w.name)}</b></td><td>${esc(w.trigger_key)}</td><td>${esc(w.action_key)}</td><td>${badge(w.status)}</td><td>${esc(fmt(w.last_run_at,true))}</td></tr>`).join('')||'<tr><td colspan="5">No workflows yet.</td></tr>';$('#workflowActive').textContent=S.workflows.filter(x=>x.status==='active').length;$('#workflowPaused').textContent=S.workflows.filter(x=>x.status==='paused').length;$('#workflowRuns').textContent=S.workflows.reduce((a,x)=>a+Number(x.run_count||0),0);$('#workflowFailures').textContent=S.workflows.reduce((a,x)=>a+Number(x.failure_count||0),0)}catch(e){$('#workflowRows').innerHTML=`<tr><td colspan="5">${esc(e.message)}</td></tr>`}}
const section4View=view;view=function(id){section4View(id);if(id==='segments')loadSegments();if(id==='campaigns'){loadSegments();loadCampaigns()}if(id==='forms')loadForms();if(id==='workflows')loadWorkflows()}
$('#newSegment').onclick=()=>{$('#segmentForm').reset();$('#segmentModal').showModal()};$('#segmentForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/segments',{method:'POST',body:JSON.stringify({name:$('#segmentName').value,field:$('#segmentField').value,operator:$('#segmentOperator').value,value:$('#segmentValue').value})});$('#segmentModal').close();await loadSegments()}catch(x){alert(x.message)}};
$('#newCampaign').onclick=async()=>{await loadSegments();$('#campaignForm').reset();$('#campaignModal').showModal()};$('#campaignForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/campaigns',{method:'POST',body:JSON.stringify({name:$('#campaignName').value,channel:$('#campaignChannel').value,segmentId:$('#campaignSegment').value,subject:$('#campaignSubject').value,body:$('#campaignBody').value,scheduleAt:$('#campaignSchedule').value})});$('#campaignModal').close();await loadCampaigns()}catch(x){alert(x.message)}};
$('#newForm').onclick=()=>{$('#leadFormForm').reset();$('#formModal').showModal()};$('#leadFormForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/forms',{method:'POST',body:JSON.stringify({name:$('#leadFormName').value,slug:$('#leadFormSlug').value,fields:$('#leadFormFields').value.split(',').map(x=>x.trim()).filter(Boolean)})});$('#formModal').close();await loadForms()}catch(x){alert(x.message)}};
$('#newWorkflow').onclick=()=>{$('#workflowForm').reset();$('#workflowModal').showModal()};$('#workflowForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/workflows',{method:'POST',body:JSON.stringify({name:$('#workflowName').value,trigger:$('#workflowTrigger').value,action:$('#workflowAction').value,config:$('#workflowConfig').value})});$('#workflowModal').close();await loadWorkflows()}catch(x){alert(x.message)}};
