async function loadConversations(){try{const j=await call('/v1/hq/conversations'),s=j.stats||{};$('#conversationThreads').textContent=s.threads??0;$('#conversationUnmatched').textContent=s.unmatched??0;$('#conversationQuestions').textContent=s.questions??0;$('#conversationWeek').textContent=s.week??0;$('#conversationRows').innerHTML=(j.messages||[]).map(x=>`<tr><td>${esc(x.channel)}</td><td>${esc(x.address||x.member_email||'—')}</td><td>${esc(x.subject||x.body.slice(0,100))}</td><td>${badge(x.direction)}</td><td>${esc(x.member_name||x.member_email||'—')}</td><td>${esc(fmt(x.created_at,true))}</td></tr>`).join('')||'<tr><td colspan="6">No conversations yet.</td></tr>'}catch(e){$('#conversationRows').innerHTML=`<tr><td colspan="6">${esc(e.message)}</td></tr>`}}
async function loadIntelligenceLoop(){try{const j=await call('/v1/hq/intelligence-loop');$('#intelQuestions').textContent=(j.questions||[]).length;$('#intelTerms').textContent=(j.terms||[]).length;$('#intelGaps').textContent=(j.gaps||[]).length;$('#intelReview').textContent=(j.questions||[]).filter(x=>x.status==='discovered').length;$('#trendingQuestions').innerHTML=(j.questions||[]).slice(0,20).map(q=>`<div class="cms-item"><b>${esc(q.example_question)}</b><span>Asked ${q.occurrence_count} times · ${esc(q.status)}</span></div>`).join('')||'<div class="empty">No recurring questions yet.</div>';$('#contentOpportunities').innerHTML=(j.gaps||[]).slice(0,20).map(g=>`<div class="cms-item"><b>${esc(g.title)}</b><span>${esc(g.reason)} · priority ${g.priority}</span></div>`).join('')||'<div class="empty">No content gaps yet.</div>'}catch(e){$('#trendingQuestions').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadDictionary(){try{const j=await call('/v1/hq/dictionary');$('#dictionaryRows').innerHTML=(j.terms||[]).map(t=>`<tr><td><b>${esc(t.phrase)}</b></td><td>${esc(t.maps_to)}</td><td>${esc(t.category)}</td><td>${t.occurrence_count}</td><td class="term-${esc(t.status)}">${esc(t.status)}</td></tr>`).join('')||'<tr><td colspan="5">No dictionary terms yet.</td></tr>'}catch(e){$('#dictionaryRows').innerHTML=`<tr><td colspan="5">${esc(e.message)}</td></tr>`}}
async function loadKnowledgeApproval(){try{const j=await call('/v1/hq/knowledge-approval');$('#knowledgeApprovalList').innerHTML=(j.proposals||[]).map(p=>`<div class="cms-item approval-card"><b>${esc(p.question)}</b><span>${esc(p.context_summary||'')}</span>${p.status==='needs_review'||p.status==='draft'?`<textarea id="proposalAnswer${p.id}" placeholder="Approved Shift answer…">${esc(p.proposed_answer||'')}</textarea><div class="row-actions"><button onclick="reviewKnowledge(${p.id},'approve')">Approve into Shift Brain</button><button class="ghost" onclick="reviewKnowledge(${p.id},'reject')">Reject</button></div>`:`<span>${badge(p.status)}</span>`}</div>`).join('')||'<div class="empty">Nothing awaiting review.</div>'}catch(e){$('#knowledgeApprovalList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
window.reviewKnowledge=async(id,decision)=>{try{const answer=document.getElementById('proposalAnswer'+id)?.value||'';await call(`/v1/hq/knowledge-approval/${id}/${decision}`,{method:'POST',body:JSON.stringify({answer})});await loadKnowledgeApproval()}catch(e){alert(e.message)}}
async function loadSetupWizard(){try{const j=await call('/v1/hq/setup/status');$('#setupGrid').innerHTML=(j.checks||[]).map(c=>`<article class="product-card"><div class="sku">${esc(c.status.toUpperCase())}</div><h3>${esc(c.name)}</h3><p class="sub">${esc(c.detail)}</p></article>`).join('')}catch(e){$('#setupGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
const section10View=view;view=function(id){section10View(id);if(id==='conversations')loadConversations();if(id==='intelloop')loadIntelligenceLoop();if(id==='dictionary')loadDictionary();if(id==='knowledgeapproval')loadKnowledgeApproval();if(id==='setupwizard')loadSetupWizard()}
$('#refreshConversations').onclick=loadConversations;
$('#runIntelligenceLoop').onclick=async()=>{const b=$('#runIntelligenceLoop');b.disabled=true;b.textContent='Analysing…';try{const j=await call('/v1/hq/intelligence-loop/run',{method:'POST',body:'{}'});alert(`Processed ${j.questionsProcessed} question signals and ${j.termsProcessed} terminology signals.`);await loadIntelligenceLoop();await loadDictionary();await loadKnowledgeApproval()}catch(e){alert(e.message)}finally{b.disabled=false;b.textContent='Analyse conversations'}};
$('#refreshDictionary').onclick=loadDictionary;
$('#refreshKnowledgeApproval').onclick=loadKnowledgeApproval;
$('#runSetupChecks').onclick=loadSetupWizard;
$('#setupSeedData').onclick=async()=>{try{await call('/v1/hq/setup/seed',{method:'POST',body:'{}'});alert('Shift HQ defaults seeded.');loadSetupWizard()}catch(e){alert(e.message)}};
$('#setupIndexSite').onclick=async()=>{try{const j=await call('/v1/hq/ai/indexing/run',{method:'POST',body:'{}'});alert(`Indexed ${j.pages} pages.`);loadSetupWizard()}catch(e){alert(e.message)}};
$('#setupRunAcademy').onclick=async()=>{try{const j=await call('/v1/hq/ai/evaluations/run',{method:'POST',body:'{}'});alert(`${j.pass}/${j.total} Academy tests passed automatically.`);loadSetupWizard()}catch(e){alert(e.message)}};
$('#setupRunSynthetic').onclick=async()=>{try{const j=await call('/v1/hq/ai/synthetic/run',{method:'POST',body:'{}'});alert(`${j.pass}/${j.total} Synthetic Shifter tests passed.`);loadSetupWizard()}catch(e){alert(e.message)}};
load();
function money(pence){return new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format((Number(pence)||0)/100)}
async function loadProducts(){try{const j=await call('/v1/hq/products');S.products=j.products||[];$('#productGrid').innerHTML=S.products.length?S.products.map(p=>`<article class="product-card"><div class="sku">${esc(p.sku)} · ${esc(p.product_type)}</div><h3>${esc(p.name)}</h3><p class="sub">${esc(p.description||'No description yet.')}</p><div class="price">${money(p.price_pence)}</div><footer>${badge(p.status)}<small>${esc(fmt(p.updated_at))}</small></footer>${p.product_type==='physical'?`<button type="button" data-inventory-product="${Number(p.id)}">Manage stock</button>`:''}</article>`).join(''):'<div class="empty">No products yet.</div>';$$('[data-inventory-product]').forEach(b=>b.onclick=()=>openInventory(Number(b.dataset.inventoryProduct)));$('#orderProduct').innerHTML=S.products.filter(p=>p.status==='active').map(p=>`<option value="${p.id}">${esc(p.name)} — ${money(p.price_pence)}</option>`).join('')}catch(e){$('#productGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadOrders(){try{const j=await call('/v1/hq/orders');S.orders=j.orders||[];if($('#orderEnvironment')&&!$('#orderEnvironment').dataset.chosen)$('#orderEnvironment').value=j.mode==='live'?'live':'test';renderOrders()}catch(e){$('#orderRows').innerHTML=`<tr><td colspan="6">${esc(e.message)}</td></tr>`}}
function renderOrders(){const f=$('#orderFilter')?.value||'all',environment=$('#orderEnvironment')?.value||'live',scope=environment==='all'?S.orders:S.orders.filter(o=>o.environment===environment),a=f==='all'?scope:scope.filter(o=>o.status===f);$('#orderRows').innerHTML=a.length?a.map(o=>`<tr data-order-id="${Number(o.id)}" style="cursor:pointer"><td><b>#${esc(o.order_number)}</b><br><small>${esc(o.product_name||'Custom order')}${o.size?' · Size '+esc(o.size):''} · ${esc(o.environment||'manual')}</small></td><td>${esc(o.customer_name||'—')}<br><small>${esc(o.customer_email||'—')}</small></td><td>${badge(o.status)}</td><td class="money">${money(o.total_pence)}</td><td>${badge(o.payment_status)}</td><td>${esc(fmt(o.created_at))}</td></tr>`).join(''):'<tr><td colspan="6">No orders in this view.</td></tr>';$$('#orderRows tr[data-order-id]').forEach(row=>row.onclick=()=>openOrder(Number(row.dataset.orderId)));$('#orderCount').textContent=scope.length;$('#orderRevenue').textContent=money(scope.filter(o=>o.payment_status==='paid').reduce((n,o)=>n+Number(o.total_pence||0),0));$('#orderOpen').textContent=scope.filter(o=>!['fulfilled','refunded','cancelled'].includes(o.status)).length;$('#orderRefunded').textContent=scope.filter(o=>o.status==='refunded'||o.payment_status==='refunded').length;$('#orderCountLabel').textContent=environment==='all'?'all environments':environment+' commerce';$('#orderRevenueLabel').textContent=environment==='all'?'all paid gross':environment+' paid gross'}
function jsonObject(v){try{return JSON.parse(v||'{}')}catch{return {}}}
function addressText(v){const a=jsonObject(v);return [a.line1,a.line2,a.city,a.postal_code,a.country].filter(Boolean).map(esc).join('<br>')||'Not supplied yet'}
function openOrder(id){const o=S.orders.find(x=>Number(x.id)===id);if(!o)return;let d=$('#fulfilmentOrder');if(!d){d=document.createElement('dialog');d.id='fulfilmentOrder';d.style.cssText='width:min(760px,calc(100% - 28px));border:1px solid #7f876f;border-radius:20px;background:#10110e;color:#f1eee5;padding:0';document.body.appendChild(d)}const n=jsonObject(o.notes);d.innerHTML=`<form method="dialog" style="padding:24px"><button style="float:right" aria-label="Close">×</button><p class="eyebrow">ORDER ${esc(o.order_number)} · ${esc(o.environment||'manual')}</p><h2>${esc(o.product_name||'Shift order')}</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0"><div class="card"><b>Customer</b><p>${esc(o.customer_name||'—')}<br>${esc(o.customer_email||'—')}</p></div><div class="card"><b>Order</b><p>${o.size?'Size '+esc(o.size)+' · ':''}Quantity ${Number(o.quantity||1)}<br>${money(o.total_pence)} · ${esc(o.payment_status)}</p></div><div class="card"><b>Delivery address</b><p>${addressText(o.shipping_address_json)}</p></div><div class="card"><b>Stripe</b><p style="word-break:break-all">${esc(o.stripe_payment_intent_id||'Awaiting payment reference')}</p></div></div><label>Status<select id="fulfilmentStatus"><option value="paid">Payment confirmed</option><option value="processing">Processing</option><option value="dispatched">Dispatched</option><option value="fulfilled">Fulfilled</option><option value="cancelled">Cancelled</option></select></label><label>Carrier<input id="fulfilmentCarrier" value="${esc(n.carrier||'')}" placeholder="Royal Mail, DPD…"></label><label>Tracking reference<input id="fulfilmentTracking" value="${esc(n.trackingReference||'')}"></label><p><button type="button" class="primary" id="saveFulfilment">Save update</button>${o.payment_status==='paid'?` <button type="button" id="refundOrder">Refund payment</button>`:''}${o.payment_status==='refunded'?` <button type="button" id="refundEmail">Send refund email</button>`:''} <small id="fulfilmentMessage"></small></p><p style="color:#aaa69d">Choosing Dispatched sends the branded dispatch email and updates the customer’s My Shift timeline. Refund payment performs the real Stripe refund and emails the customer automatically.</p></form>`;if([...$('#fulfilmentStatus').options].some(x=>x.value===o.status))$('#fulfilmentStatus').value=o.status;$('#saveFulfilment').onclick=async()=>{const b=$('#saveFulfilment'),m=$('#fulfilmentMessage');b.disabled=true;m.textContent='Saving…';try{await call(`/v1/hq/orders/${id}`,{method:'PATCH',body:JSON.stringify({status:$('#fulfilmentStatus').value,carrier:$('#fulfilmentCarrier').value,trackingReference:$('#fulfilmentTracking').value})});m.textContent='Saved.';await loadOrders();setTimeout(()=>d.close(),500)}catch(e){m.textContent=e.message}finally{b.disabled=false}};if($('#refundOrder'))$('#refundOrder').onclick=async()=>{if(!confirm(`Refund ${money(o.total_pence)} to this customer through Stripe? This cannot be undone.`))return;const reason=prompt('Internal refund reason (optional):')||'',b=$('#refundOrder'),m=$('#fulfilmentMessage');b.disabled=true;m.textContent='Refunding through Stripe…';try{const result=await call(`/v1/hq/orders/${id}/refund`,{method:'POST',body:JSON.stringify({reason})});m.textContent=`Refunded ${money(result.amountPence)} via Stripe.${result.refundEmailSent?' Customer email sent.':' Customer email could not be sent.'}`;await loadOrders();setTimeout(()=>d.close(),1400)}catch(e){m.textContent=e.message;b.disabled=false}};if($('#refundEmail'))$('#refundEmail').onclick=async()=>{const b=$('#refundEmail'),m=$('#fulfilmentMessage');b.disabled=true;m.textContent='Sending refund email…';try{await call(`/v1/hq/orders/${id}/refund-email`,{method:'POST',body:'{}'});m.textContent='Refund email sent to the customer.'}catch(e){m.textContent=e.message;b.disabled=false}};d.showModal()}
async function openInventory(productId){const p=S.products.find(x=>Number(x.id)===productId),j=await call(`/v1/hq/products/${productId}/inventory`);let d=$('#inventoryDialog');if(!d){d=document.createElement('dialog');d.id='inventoryDialog';d.className='wide-dialog';document.body.appendChild(d)}d.innerHTML=`<form method="dialog"><button style="float:right" aria-label="Close">×</button><h2>Stock · ${esc(p?.name||'Product')}</h2><p class="sub">Leave a size unlimited until physical stock counting begins, or set an exact quantity. Reserved checkout stock is shown separately.</p><div style="display:grid;gap:10px">${(j.inventory||[]).map(x=>`<div class="card" style="display:grid;grid-template-columns:60px 1fr auto;gap:10px;align-items:center"><b>${esc(x.size)}</b><input data-stock-size="${esc(x.size)}" type="number" min="0" placeholder="Unlimited" value="${x.stock_on_hand===null?'':Number(x.stock_on_hand)}"><span>${Number(x.reserved||0)} reserved</span><label><input data-stock-active="${esc(x.size)}" type="checkbox" ${Number(x.active)?'checked':''}> Available</label><button type="button" data-save-stock="${esc(x.size)}">Save</button></div>`).join('')}</div><p id="inventoryMessage"></p></form>`;$$('[data-save-stock]').forEach(b=>b.onclick=async()=>{const size=b.dataset.saveStock,input=$(`[data-stock-size="${size}"]`),active=$(`[data-stock-active="${size}"]`).checked,m=$('#inventoryMessage');b.disabled=true;try{await call(`/v1/hq/products/${productId}/inventory`,{method:'PATCH',body:JSON.stringify({size,active,unlimited:input.value==='',stockOnHand:input.value===''?null:Number(input.value)})});m.textContent=`${size} stock saved.`}catch(e){m.textContent=e.message}finally{b.disabled=false}});d.showModal()}
async function loadContent(){try{const j=await call('/v1/hq/content');S.content=j.content||[];$('#contentList').innerHTML=S.content.length?S.content.map(c=>`<div class="cms-item"><b>${esc(c.label)}</b><span>${esc(c.content_key)} · ${esc(c.status)} · ${esc(c.page||'global')}</span><span>${esc((c.content_value||'').slice(0,120))}</span></div>`).join(''):'<div class="empty">No managed content blocks yet.</div>'}catch(e){$('#contentList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadArticles(){try{const j=await call('/v1/hq/articles');S.articles=j.articles||[];$('#articleRows').innerHTML=S.articles.length?S.articles.map(a=>`<tr><td><b>${esc(a.title)}</b><br><small>/${esc(a.slug)}</small></td><td>${badge(a.status)}</td><td>${esc(a.category||'—')}</td><td>${esc(a.author||'—')}</td><td>${esc(fmt(a.publish_at))}</td><td>${esc(fmt(a.updated_at))}</td></tr>`).join(''):'<tr><td colspan="6">No Knowledge Hub articles yet.</td></tr>'}catch(e){$('#articleRows').innerHTML=`<tr><td colspan="6">${esc(e.message)}</td></tr>`}}
const oldView=view;view=function(id){oldView(id);if(id==='orders'){loadOrders();loadProducts()}if(id==='products')loadProducts();if(id==='website')loadContent();if(id==='knowledge')loadArticles()}
$('#orderFilter').onchange=renderOrders;
$('#orderEnvironment').onchange=()=>{$('#orderEnvironment').dataset.chosen='1';renderOrders()};
$('#newOrder').onclick=async()=>{await loadProducts();$('#orderForm').reset();$('#orderQty').value=1;$('#orderModal').showModal()};
$('#newProduct').onclick=()=>{$('#productForm').reset();$('#productModal').showModal()};
$('#newContent').onclick=()=>{$('#contentForm').reset();$('#contentModal').showModal()};
$('#newArticle').onclick=()=>{$('#articleForm').reset();$('#articleModal').showModal()};
$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
$('#productForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/products',{method:'POST',body:JSON.stringify({name:$('#productName').value,sku:$('#productSku').value,productType:$('#productType').value,pricePence:Math.round(Number($('#productPrice').value)*100),status:$('#productStatus').value,description:$('#productDescription').value})});$('#productModal').close();await loadProducts()}catch(err){alert(err.message)}};
$('#orderForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/orders',{method:'POST',body:JSON.stringify({customerEmail:$('#orderEmail').value,customerName:$('#orderName').value,productId:Number($('#orderProduct').value||0),quantity:Number($('#orderQty').value||1),paymentStatus:$('#orderPayment').value,status:$('#orderStatus').value,notes:$('#orderNotes').value})});$('#orderModal').close();await loadOrders()}catch(err){alert(err.message)}};
$('#contentForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/content',{method:'POST',body:JSON.stringify({contentKey:$('#contentKey').value,label:$('#contentLabel').value,contentValue:$('#contentValue').value,status:$('#contentStatus').value,page:$('#contentPage').value})});$('#contentModal').close();await loadContent()}catch(err){alert(err.message)}};
$('#articleForm').onsubmit=async e=>{e.preventDefault();try{await call('/v1/hq/articles',{method:'POST',body:JSON.stringify({title:$('#articleTitle').value,slug:$('#articleSlug').value,category:$('#articleCategory').value,author:$('#articleAuthor').value,status:$('#articleStatus').value,summary:$('#articleSummary').value,body:$('#articleBody').value,seoTitle:$('#articleSeoTitle').value,publishAt:$('#articlePublishAt').value||null})});$('#articleModal').close();await loadArticles()}catch(err){alert(err.message)}};
